import AsyncStorage from "@react-native-async-storage/async-storage";

export const zpl0 =
  "CT~~CD,~CC^~CT~" +
  "^XA~TA000~JSN^LT0^MNW^MTT^PON^PMN^LH0,0^JMA^PR6,6~SD15^JUS^LRN^CI0^XZ" +
  "^XA^MMT^PW831^LL1685^LS0" +
  "^FO32,0^GFA,08448,08448,00044,:Z64:" +
  ":1590" +
  "^BY5,3,219^FT58,420^BCN,,Y,N" +
  "^FD>:PALNUMVAR^FS" + // ← C'est cette ligne (^FD>:PALNUMVAR) qui crée le code-barres !
  "^FO86,163^GB688,0,8^FS" +
  "^FT104,598^A0N,127,124^FH\\^FDPALNUMVAR^FS" +
  "^FT38,753^A0N,68,67^FH\\\\^FDDESIGNATIONARTICLE^FS" +
  "^FT38,668^A0N,68,67^FH\\^FDREFARTICLE^FS" +
  "^FT38,863^A0N,68,67^FH\\\\^FDDESIGNATION_LIGNE_2^FS" +
  "^FO69,885^GB688,0,8^FS" +
  "^FT38,959^A0N,51,50^FH\\^FDNUMOF:       NUMOF^FS" +
  "^FT38,1025^A0N,51,50^FH\\^FDQUANTITE:   QTY_VAR^FS" +
  "^FO55,1126^GB688,0,8^FS" +
  "^FT45,1223^A0N,68,67^FH\\^FDLOT N: LOT_VAR^FS" +
  "^FT57,1294^A0N,55,55^FH\\^FDSLOT^FS" +
  "^FT272,1296^A0N,55,55^FH\\^FDQTY^FS" +
  "^FT37,1105^A0N,79,76^FH\\\\^FDD.PROD : DD/MM/YYYY^FS" +
  "^FT616,131^A0N,34,33^FH\\\\^FDusername^FS" +
  "^PQ1,0,1,Y^XZ";

export interface LigneProduction {
  id?: string;
  lot: string;
  slot: string;
  quantite: string;
}

export interface ZplData {
  palette: string;
  of: string;
  designation: string;
  designation2?: string;
  matricule: string;
  lignes: LigneProduction[];
  zpcu?: string;        // ✅ Ajouté
  zpcustucoe?: string;  // ✅ Ajouté
  zshl?: string;        // ✅ Ajouté
}

export const generateZplLabel = (data: ZplData): string => {
  const { palette, of: ofRef, designation, designation2, matricule, lignes } = data;

  const now = new Date();
  const dd = String(now.getDate()).padStart(2, "0");
  const mm = String(now.getMonth() + 1).padStart(2, "0");
  const yyyy = now.getFullYear();
  const dateProd = `${dd}/${mm}/${yyyy}`;

  // Calcul correct de la quantité totale même si le formulaire a été vidé
  const totalQty = lignes && lignes.length > 0 
    ? lignes.reduce((acc, l) => acc + parseInt(l.quantite || "0", 10), 0)
    : 0;

  const premierLot = lignes && lignes.length > 0 ? lignes[0] : { lot: "", slot: "", quantite: "0" };

  let zpl = zpl0;

  // Remplacement global du numéro de palette (Texte + Code-barres)
  zpl = zpl.replace(/PALNUMVAR/g, palette);
  zpl = zpl.replace(/REFARTICLE/g, ofRef);

  const des1 = designation.length > 30 ? designation.substring(0, 30) : designation;
  const des2 = designation2 || (designation.length > 30 ? designation.substring(30) : "");
  zpl = zpl.replace(/DESIGNATIONARTICLE/g, des1);
  zpl = zpl.replace(/DESIGNATION_LIGNE_2/g, des2);

  zpl = zpl.replace(/NUMOF/g, ofRef);
  zpl = zpl.replace(/QTY_VAR/g, String(totalQty));
  zpl = zpl.replace(/DD\/MM\/YYYY/g, dateProd);
  zpl = zpl.replace(/username/g, matricule);

  // Remplacement des données du premier lot
  zpl = zpl.replace(/LOT_VAR/g, premierLot.lot);
  zpl = zpl.replace(/\bSLOT\b/g, premierLot.slot);
  zpl = zpl.replace(/\bQTY\b/g, premierLot.quantite);

  // Si ton template initial intégrait aussi ZPCU, ZPCUSTUCOE ou ZSHL textuellement,
  // tu pourrais ajouter des lignes .replace() ici.

  return zpl;
};

export const sendToPrinter = async (zplCode: string): Promise<boolean> => {
  try {
    const storedIp = await AsyncStorage.getItem("printer_ip");
    const printerUrl = storedIp ? `http://${storedIp}` : "http://172.16.11.231:6101";

    console.log("📡 Envoi ZPL vers :", printerUrl);

    const response = await fetch(printerUrl, {
      method: "POST",
      headers: { "Content-Type": "text/plain" },
      body: zplCode,
    });

    return response.ok;
  } catch (error) {
    console.error("❌ Erreur imprimante :", error);
    return false;
  }
};